// Ce dictionnaire est lu après tr_restes.dart (voir tr.dart). Langues : en, es, de, ar, pt, zh, sw (à faire relire par des locuteurs natifs).
const Map<String, Map<String, String>> kTrAudit = {
  // ── E-mail non confirmé (403 `email_unverified`) : fenêtre « Confirme ton e-mail » ──
  'Confirme ton e-mail pour utiliser cette fonction.': {'en': 'Confirm your email to use this feature.', 'es': 'Confirma tu correo electrónico para usar esta función.', 'de': 'Bestätige deine E-Mail-Adresse, um diese Funktion zu nutzen.', 'ar': 'أكّد بريدك الإلكتروني لاستخدام هذه الميزة.', 'pt': 'Confirme seu e-mail para usar este recurso.', 'zh': '请先确认你的邮箱，才能使用此功能。', 'sw': 'Thibitisha barua pepe yako ili utumie kipengele hiki.'},
  'Confirme ton e-mail': {'en': 'Confirm your email', 'es': 'Confirma tu correo electrónico', 'de': 'Bestätige deine E-Mail-Adresse', 'ar': 'أكّد بريدك الإلكتروني', 'pt': 'Confirme seu e-mail', 'zh': '请确认你的邮箱', 'sw': 'Thibitisha barua pepe yako'},
  "Pour utiliser cette fonction (argent, pièces, retraits), confirme ton adresse e-mail {a}. Touche « Renvoyer le lien », ouvre le message reçu, puis reviens ici et touche « J'ai confirmé ».": {'en': 'To use this feature (money, coins, withdrawals), confirm your email address {a}. Tap "Resend the link", open the message you receive, then come back here and tap "I have confirmed".', 'es': 'Para usar esta función (dinero, monedas, retiros), confirma tu correo {a}. Toca "Reenviar el enlace", abre el mensaje recibido, vuelve aquí y toca "Ya confirmé".', 'de': 'Um diese Funktion (Geld, Münzen, Auszahlungen) zu nutzen, bestätige deine E-Mail-Adresse {a}. Tippe auf "Link erneut senden", öffne die erhaltene Nachricht, komm dann hierher zurück und tippe auf "Ich habe bestätigt".', 'ar': 'لاستخدام هذه الميزة (المال، العملات، السحوبات)، أكّد عنوان بريدك الإلكتروني {a}. اضغط على "إعادة إرسال الرابط"، افتح الرسالة التي تصلك، ثم عد إلى هنا واضغط على "لقد أكّدت".', 'pt': 'Para usar este recurso (dinheiro, moedas, saques), confirme seu e-mail {a}. Toque em "Reenviar o link", abra a mensagem recebida, volte aqui e toque em "Já confirmei".', 'zh': '要使用此功能（资金、金币、提现），请先确认你的邮箱 {a}。点击“重新发送链接”，打开收到的邮件，然后回到这里点击“我已确认”。', 'sw': 'Ili kutumia kipengele hiki (pesa, sarafu, uondoaji), thibitisha barua pepe yako {a}. Gusa "Tuma kiungo tena", fungua ujumbe utakaopokea, kisha rudi hapa na ugonge "Nimethibitisha".'},
  'Pour utiliser cette fonction, ton compte doit avoir une adresse e-mail confirmée. Ajoute-en une dans les réglages de ton compte.': {'en': 'To use this feature, your account must have a confirmed email address. Add one in your account settings.', 'es': 'Para usar esta función, tu cuenta debe tener un correo electrónico confirmado. Añade uno en los ajustes de tu cuenta.', 'de': 'Um diese Funktion zu nutzen, braucht dein Konto eine bestätigte E-Mail-Adresse. Füge in den Kontoeinstellungen eine hinzu.', 'ar': 'لاستخدام هذه الميزة، يجب أن يحتوي حسابك على عنوان بريد إلكتروني مؤكَّد. أضف عنوانًا في إعدادات حسابك.', 'pt': 'Para usar este recurso, sua conta precisa ter um e-mail confirmado. Adicione um nas configurações da conta.', 'zh': '要使用此功能，你的账号需要有已确认的邮箱。请在账号设置中添加。', 'sw': 'Ili kutumia kipengele hiki, akaunti yako lazima iwe na barua pepe iliyothibitishwa. Weka moja katika mipangilio ya akaunti yako.'},
  'Lien envoyé. Ouvre ta boîte mail (et le dossier des courriers indésirables), puis touche le lien.': {'en': 'Link sent. Open your inbox (and the spam folder), then tap the link.', 'es': 'Enlace enviado. Abre tu bandeja de entrada (y la carpeta de spam) y toca el enlace.', 'de': 'Link gesendet. Öffne dein Postfach (und den Spam-Ordner) und tippe auf den Link.', 'ar': 'تم إرسال الرابط. افتح صندوق بريدك (ومجلد الرسائل غير المرغوب فيها) ثم اضغط على الرابط.', 'pt': 'Link enviado. Abra sua caixa de entrada (e a pasta de spam) e toque no link.', 'zh': '链接已发送。请打开你的收件箱（以及垃圾邮件文件夹），然后点击链接。', 'sw': 'Kiungo kimetumwa. Fungua kikasha chako (na folda ya barua taka), kisha gusa kiungo.'},
  'Trop de demandes. Patiente quelques minutes avant de renvoyer le lien.': {'en': 'Too many requests. Wait a few minutes before resending the link.', 'es': 'Demasiadas solicitudes. Espera unos minutos antes de reenviar el enlace.', 'de': 'Zu viele Anfragen. Warte ein paar Minuten, bevor du den Link erneut sendest.', 'ar': 'طلبات كثيرة جدًا. انتظر بضع دقائق قبل إعادة إرسال الرابط.', 'pt': 'Muitas solicitações. Aguarde alguns minutos antes de reenviar o link.', 'zh': '请求过于频繁。请等待几分钟后再重新发送链接。', 'sw': 'Maombi mengi mno. Subiri dakika chache kabla ya kutuma kiungo tena.'},
  "Le lien n'a pas pu être envoyé. Vérifie ta connexion puis réessaie.": {'en': 'The link could not be sent. Check your connection and try again.', 'es': 'No se pudo enviar el enlace. Comprueba tu conexión y vuelve a intentarlo.', 'de': 'Der Link konnte nicht gesendet werden. Prüfe deine Verbindung und versuche es erneut.', 'ar': 'تعذّر إرسال الرابط. تحقق من اتصالك ثم أعد المحاولة.', 'pt': 'Não foi possível enviar o link. Verifique sua conexão e tente novamente.', 'zh': '链接发送失败。请检查网络后重试。', 'sw': 'Kiungo hakikutumwa. Angalia muunganisho wako kisha jaribu tena.'},
  "Ton e-mail n'est pas encore confirmé. Touche le lien reçu par e-mail, puis reviens ici.": {'en': 'Your email is not confirmed yet. Tap the link you received by email, then come back here.', 'es': 'Tu correo aún no está confirmado. Toca el enlace que recibiste por correo y vuelve aquí.', 'de': 'Deine E-Mail-Adresse ist noch nicht bestätigt. Tippe auf den Link in der E-Mail und komm dann hierher zurück.', 'ar': 'لم يتم تأكيد بريدك الإلكتروني بعد. اضغط على الرابط الذي وصلك بالبريد ثم عد إلى هنا.', 'pt': 'Seu e-mail ainda não foi confirmado. Toque no link recebido por e-mail e volte aqui.', 'zh': '你的邮箱尚未确认。请点击邮件中的链接，然后回到这里。', 'sw': 'Barua pepe yako bado haijathibitishwa. Gusa kiungo ulichopokea kwa barua pepe, kisha rudi hapa.'},
  "La vérification n'a pas pu être faite. Vérifie ta connexion puis réessaie.": {'en': 'The check could not be done. Check your connection and try again.', 'es': 'No se pudo hacer la verificación. Comprueba tu conexión y vuelve a intentarlo.', 'de': 'Die Prüfung konnte nicht durchgeführt werden. Prüfe deine Verbindung und versuche es erneut.', 'ar': 'تعذّر إجراء التحقق. تحقق من اتصالك ثم أعد المحاولة.', 'pt': 'Não foi possível fazer a verificação. Verifique sua conexão e tente novamente.', 'zh': '无法完成验证。请检查网络后重试。', 'sw': 'Uhakiki haukuweza kufanyika. Angalia muunganisho wako kisha jaribu tena.'},
  'Renvoyer le lien': {'en': 'Resend the link', 'es': 'Reenviar el enlace', 'de': 'Link erneut senden', 'ar': 'إعادة إرسال الرابط', 'pt': 'Reenviar o link', 'zh': '重新发送链接', 'sw': 'Tuma kiungo tena'},
  "J'ai confirmé": {'en': 'I have confirmed', 'es': 'Ya confirmé', 'de': 'Ich habe bestätigt', 'ar': 'لقد أكّدت', 'pt': 'Já confirmei', 'zh': '我已确认', 'sw': 'Nimethibitisha'},

  // ── Conversion des pièces gagnées : lots de 25 (422 `coins_not_multiple`) ──
  'Les pièces se convertissent par lots de {n}. Choisis un multiple de {n} : le montant est arrondi vers le bas.': {'en': 'Coins are converted in batches of {n}. Choose a multiple of {n}: the amount is rounded down.', 'es': 'Las monedas se convierten en lotes de {n}. Elige un múltiplo de {n}: la cantidad se redondea hacia abajo.', 'de': 'Münzen werden in Paketen von {n} umgewandelt. Wähle ein Vielfaches von {n}: Der Betrag wird abgerundet.', 'ar': 'تُحوَّل العملات على دفعات من {n}. اختر مضاعفًا للعدد {n}: يُقرَّب المبلغ إلى الأسفل.', 'pt': 'As moedas são convertidas em lotes de {n}. Escolha um múltiplo de {n}: o valor é arredondado para baixo.', 'zh': '金币按每 {n} 个一批进行兑换。请选择 {n} 的倍数：数量将向下取整。', 'sw': 'Sarafu hubadilishwa kwa vifurushi vya {n}. Chagua kizidisho cha {n}: kiasi hupunguzwa hadi kizidisho cha chini.'},
  'Arrondi vers le bas : {a} pièces seront converties (conversion par lots de {b} pièces).': {'en': 'Rounded down: {a} coins will be converted (conversion in batches of {b} coins).', 'es': 'Redondeado hacia abajo: se convertirán {a} monedas (conversión en lotes de {b} monedas).', 'de': 'Abgerundet: {a} Münzen werden umgewandelt (Umwandlung in Paketen von {b} Münzen).', 'ar': 'تقريب إلى الأسفل: سيتم تحويل {a} عملة (التحويل على دفعات من {b} عملة).', 'pt': 'Arredondado para baixo: {a} moedas serão convertidas (conversão em lotes de {b} moedas).', 'zh': '已向下取整：将兑换 {a} 个金币（每 {b} 个金币一批）。', 'sw': 'Imepunguzwa: sarafu {a} zitabadilishwa (ubadilishaji kwa vifurushi vya sarafu {b}).'},
  'Minimum {a} pièces par conversion, par lots de {b} pièces (le surplus est arrondi vers le bas). Le montant est ajouté à votre Solde Gains.': {'en': 'Minimum {a} coins per conversion, in batches of {b} coins (any remainder is rounded down). The amount is added to your Earnings balance.', 'es': 'Mínimo {a} monedas por conversión, en lotes de {b} monedas (el sobrante se redondea hacia abajo). El importe se añade a tu saldo de ganancias.', 'de': 'Mindestens {a} Münzen pro Umwandlung, in Paketen von {b} Münzen (der Rest wird abgerundet). Der Betrag wird deinem Gewinnguthaben gutgeschrieben.', 'ar': 'الحد الأدنى {a} عملة لكل تحويل، على دفعات من {b} عملة (يُقرَّب الباقي إلى الأسفل). تُضاف القيمة إلى رصيد أرباحك.', 'pt': 'Mínimo de {a} moedas por conversão, em lotes de {b} moedas (o resto é arredondado para baixo). O valor é adicionado ao seu saldo de ganhos.', 'zh': '每次兑换至少 {a} 个金币，按每 {b} 个金币一批（余数向下取整）。金额将计入你的收益余额。', 'sw': 'Kima cha chini ni sarafu {a} kwa kila ubadilishaji, kwa vifurushi vya sarafu {b} (kinachobaki hupunguzwa). Kiasi huongezwa kwenye salio lako la mapato.'},
  'Seules tes pièces gagnées sont convertibles.': {'en': 'Only your earned coins can be converted.', 'es': 'Solo tus monedas ganadas se pueden convertir.', 'de': 'Nur deine verdienten Münzen können umgewandelt werden.', 'ar': 'العملات التي ربحتها فقط قابلة للتحويل.', 'pt': 'Somente suas moedas ganhas podem ser convertidas.', 'zh': '只有你赚取的金币可以兑换。', 'sw': 'Ni sarafu ulizopata tu ndizo zinazoweza kubadilishwa.'},

  // ── Refus de l'API : retraits, encaissement des vues, plafonds ──
  'Le montant est inférieur au minimum de retrait.': {'en': 'The amount is below the minimum withdrawal.', 'es': 'El importe es inferior al mínimo de retiro.', 'de': 'Der Betrag liegt unter dem Mindestbetrag für Auszahlungen.', 'ar': 'المبلغ أقل من الحد الأدنى للسحب.', 'pt': 'O valor é inferior ao mínimo de saque.', 'zh': '金额低于最低提现额度。', 'sw': 'Kiasi ni chini ya kima cha chini cha uondoaji.'},
  "Le montant est inférieur au minimum d'encaissement.": {'en': 'The amount is below the minimum you can cash in.', 'es': 'El importe es inferior al mínimo que se puede cobrar.', 'de': 'Der Betrag liegt unter dem Mindestbetrag für die Einlösung.', 'ar': 'المبلغ أقل من الحد الأدنى للتحصيل.', 'pt': 'O valor é inferior ao mínimo para resgatar.', 'zh': '金额低于最低可提取额度。', 'sw': 'Kiasi ni chini ya kima cha chini cha kuchukua.'},
  'Le montant est inférieur au minimum autorisé.': {'en': 'The amount is below the minimum allowed.', 'es': 'El importe es inferior al mínimo permitido.', 'de': 'Der Betrag liegt unter dem erlaubten Mindestbetrag.', 'ar': 'المبلغ أقل من الحد الأدنى المسموح به.', 'pt': 'O valor é inferior ao mínimo permitido.', 'zh': '金额低于允许的最低额度。', 'sw': 'Kiasi ni chini ya kima cha chini kinachoruhusiwa.'},
  'Ton compte est trop récent pour retirer de l’argent. Réessaie dans quelques jours.': {'en': 'Your account is too new to withdraw money. Try again in a few days.', 'es': 'Tu cuenta es demasiado reciente para retirar dinero. Inténtalo de nuevo en unos días.', 'de': 'Dein Konto ist zu neu, um Geld auszuzahlen. Versuche es in ein paar Tagen erneut.', 'ar': 'حسابك حديث جدًا لسحب الأموال. أعد المحاولة بعد بضعة أيام.', 'pt': 'Sua conta é muito recente para sacar dinheiro. Tente novamente em alguns dias.', 'zh': '你的账号太新，暂时无法提现。请过几天再试。', 'sw': 'Akaunti yako ni mpya mno kuondoa pesa. Jaribu tena baada ya siku chache.'},
  'Ton compte est trop récent pour encaisser tes gains de vues. Réessaie dans quelques jours.': {'en': 'Your account is too new to cash in your view earnings. Try again in a few days.', 'es': 'Tu cuenta es demasiado reciente para cobrar tus ganancias por vistas. Inténtalo de nuevo en unos días.', 'de': 'Dein Konto ist zu neu, um deine Aufruf-Einnahmen einzulösen. Versuche es in ein paar Tagen erneut.', 'ar': 'حسابك حديث جدًا لتحصيل أرباح المشاهدات. أعد المحاولة بعد بضعة أيام.', 'pt': 'Sua conta é muito recente para resgatar os ganhos de visualizações. Tente novamente em alguns dias.', 'zh': '你的账号太新，暂时无法提取浏览收益。请过几天再试。', 'sw': 'Akaunti yako ni mpya mno kuchukua mapato ya mitazamo. Jaribu tena baada ya siku chache.'},
  'Ton compte est trop récent pour cette opération. Réessaie dans quelques jours.': {'en': 'Your account is too new for this operation. Try again in a few days.', 'es': 'Tu cuenta es demasiado reciente para esta operación. Inténtalo de nuevo en unos días.', 'de': 'Dein Konto ist für diesen Vorgang zu neu. Versuche es in ein paar Tagen erneut.', 'ar': 'حسابك حديث جدًا لهذه العملية. أعد المحاولة بعد بضعة أيام.', 'pt': 'Sua conta é muito recente para esta operação. Tente novamente em alguns dias.', 'zh': '你的账号太新，暂时无法进行此操作。请过几天再试。', 'sw': 'Akaunti yako ni mpya mno kwa shughuli hii. Jaribu tena baada ya siku chache.'},
  'Tu as atteint le plafond de retrait des dernières 24 heures. Réessaie plus tard.': {'en': 'You have reached the withdrawal limit for the last 24 hours. Try again later.', 'es': 'Has alcanzado el límite de retiros de las últimas 24 horas. Inténtalo más tarde.', 'de': 'Du hast das Auszahlungslimit der letzten 24 Stunden erreicht. Versuche es später erneut.', 'ar': 'لقد بلغت حد السحب خلال آخر 24 ساعة. أعد المحاولة لاحقًا.', 'pt': 'Você atingiu o limite de saques das últimas 24 horas. Tente novamente mais tarde.', 'zh': '你已达到最近 24 小时的提现上限。请稍后再试。', 'sw': 'Umefikia kikomo cha uondoaji cha saa 24 zilizopita. Jaribu tena baadaye.'},
  "Tu as atteint le plafond d'encaissement du jour. Réessaie demain.": {'en': 'You have reached today\'s cash-in limit. Try again tomorrow.', 'es': 'Has alcanzado el límite de cobro de hoy. Inténtalo mañana.', 'de': 'Du hast das heutige Einlöse-Limit erreicht. Versuche es morgen erneut.', 'ar': 'لقد بلغت حد التحصيل لهذا اليوم. أعد المحاولة غدًا.', 'pt': 'Você atingiu o limite de resgate de hoje. Tente novamente amanhã.', 'zh': '你已达到今日的提取上限。请明天再试。', 'sw': 'Umefikia kikomo cha kuchukua cha leo. Jaribu tena kesho.'},
  'Tu as atteint le plafond de retrait de la semaine. Réessaie plus tard.': {'en': 'You have reached this week\'s withdrawal limit. Try again later.', 'es': 'Has alcanzado el límite de retiros de la semana. Inténtalo más tarde.', 'de': 'Du hast das Auszahlungslimit dieser Woche erreicht. Versuche es später erneut.', 'ar': 'لقد بلغت حد السحب لهذا الأسبوع. أعد المحاولة لاحقًا.', 'pt': 'Você atingiu o limite de saques da semana. Tente novamente mais tarde.', 'zh': '你已达到本周的提现上限。请稍后再试。', 'sw': 'Umefikia kikomo cha uondoaji cha wiki hii. Jaribu tena baadaye.'},
  'Un encaissement vient d’être fait. Patiente une minute avant de recommencer.': {'en': 'A cash-in has just been made. Wait a minute before trying again.', 'es': 'Acabas de cobrar. Espera un minuto antes de volver a intentarlo.', 'de': 'Es wurde gerade eine Einlösung vorgenommen. Warte eine Minute, bevor du es erneut versuchst.', 'ar': 'تم إجراء تحصيل للتو. انتظر دقيقة قبل المحاولة مجددًا.', 'pt': 'Um resgate acabou de ser feito. Aguarde um minuto antes de tentar novamente.', 'zh': '刚刚已完成一次提取。请等待一分钟后再试。', 'sw': 'Uchukuaji umefanyika sasa hivi. Subiri dakika moja kabla ya kujaribu tena.'},
  'Le montant dépasse tes gains de vues disponibles.': {'en': 'The amount is more than your available view earnings.', 'es': 'El importe supera tus ganancias por vistas disponibles.', 'de': 'Der Betrag übersteigt deine verfügbaren Aufruf-Einnahmen.', 'ar': 'المبلغ يتجاوز أرباح المشاهدات المتاحة لديك.', 'pt': 'O valor excede seus ganhos de visualizações disponíveis.', 'zh': '金额超过了你可提取的浏览收益。', 'sw': 'Kiasi kinazidi mapato yako ya mitazamo yanayopatikana.'},
  'Le service de retrait est fermé pour le moment. Il ouvre du lundi au vendredi de 8 h à 17 h et le samedi de 8 h à 14 h (heure de Lomé).': {'en': 'The withdrawal service is closed right now. It is open Monday to Friday from 8 am to 5 pm and Saturday from 8 am to 2 pm (Lomé time).', 'es': 'El servicio de retiros está cerrado en este momento. Abre de lunes a viernes de 8 h a 17 h y los sábados de 8 h a 14 h (hora de Lomé).', 'de': 'Der Auszahlungsservice ist gerade geschlossen. Er ist Montag bis Freitag von 8 bis 17 Uhr und samstags von 8 bis 14 Uhr geöffnet (Ortszeit Lomé).', 'ar': 'خدمة السحب مغلقة حاليًا. تعمل من الاثنين إلى الجمعة من 8 صباحًا إلى 5 مساءً، والسبت من 8 صباحًا إلى 2 ظهرًا (بتوقيت لومي).', 'pt': 'O serviço de saque está fechado no momento. Abre de segunda a sexta, das 8h às 17h, e aos sábados, das 8h às 14h (horário de Lomé).', 'zh': '提现服务目前已关闭。开放时间：周一至周五 8:00–17:00，周六 8:00–14:00（洛美时间）。', 'sw': 'Huduma ya uondoaji imefungwa kwa sasa. Hufunguliwa Jumatatu hadi Ijumaa saa 2 asubuhi hadi saa 11 jioni, na Jumamosi saa 2 asubuhi hadi saa 8 mchana (saa za Lomé).'},
  'Tu as une dette en cours : rembourse-la avant de continuer.': {'en': 'You have an outstanding debt: repay it before continuing.', 'es': 'Tienes una deuda pendiente: págala antes de continuar.', 'de': 'Du hast noch eine offene Schuld: Begleiche sie, bevor du fortfährst.', 'ar': 'عليك دين قائم: سدّده قبل المتابعة.', 'pt': 'Você tem uma dívida em aberto: quite-a antes de continuar.', 'zh': '你有未还清的欠款，请先还清再继续。', 'sw': 'Una deni ambalo bado halijalipwa: lilipe kabla ya kuendelea.'},
  'Ton solde est insuffisant pour ce retrait.': {'en': 'Your balance is too low for this withdrawal.', 'es': 'Tu saldo es insuficiente para este retiro.', 'de': 'Dein Guthaben reicht für diese Auszahlung nicht aus.', 'ar': 'رصيدك غير كافٍ لهذا السحب.', 'pt': 'Seu saldo é insuficiente para este saque.', 'zh': '你的余额不足，无法完成此次提现。', 'sw': 'Salio lako halitoshi kwa uondoaji huu.'},
  '{a} vues payables': {'en': '{a} payable views', 'es': '{a} vistas pagables', 'de': '{a} bezahlbare Aufrufe', 'ar': '{a} مشاهدة قابلة للدفع', 'pt': '{a} visualizações pagáveis', 'zh': '{a} 次可计费浏览', 'sw': 'Mitazamo {a} inayolipwa'},
  "Plafond d'encaissement du jour : {a}. Déjà encaissé aujourd'hui : {b}.": {'en': 'Daily cash-in limit: {a}. Already cashed in today: {b}.', 'es': 'Límite de cobro del día: {a}. Ya cobrado hoy: {b}.', 'de': 'Tageslimit für Einlösungen: {a}. Heute bereits eingelöst: {b}.', 'ar': 'حد التحصيل اليومي: {a}. المحصَّل اليوم: {b}.', 'pt': 'Limite de resgate do dia: {a}. Já resgatado hoje: {b}.', 'zh': '每日提取上限：{a}。今日已提取：{b}。', 'sw': 'Kikomo cha kuchukua cha siku: {a}. Tayari umechukua leo: {b}.'},

  // ── Défis ──
  'Tu es le créateur de ce DÉFI : tu ne peux pas y participer.': {'en': 'You created this DÉFI: you cannot take part in it.', 'es': 'Eres el creador de este DÉFI: no puedes participar en él.', 'de': 'Du hast dieses DÉFI erstellt: Du kannst nicht daran teilnehmen.', 'ar': 'أنت منشئ هذا التحدي (DÉFI): لا يمكنك المشاركة فيه.', 'pt': 'Você é o criador deste DÉFI: não pode participar dele.', 'zh': '你是此挑战（DÉFI）的创建者，不能参与。', 'sw': 'Wewe ndiye mwanzilishi wa DÉFI hii: huwezi kushiriki.'},
  'Tu es le créateur de ce DÉFI : tu ne peux pas voter pour les participants.': {'en': 'You created this DÉFI: you cannot vote for the participants.', 'es': 'Eres el creador de este DÉFI: no puedes votar por los participantes.', 'de': 'Du hast dieses DÉFI erstellt: Du kannst nicht für die Teilnehmer abstimmen.', 'ar': 'أنت منشئ هذا التحدي (DÉFI): لا يمكنك التصويت للمشاركين.', 'pt': 'Você é o criador deste DÉFI: não pode votar nos participantes.', 'zh': '你是此挑战（DÉFI）的创建者，不能为参与者投票。', 'sw': 'Wewe ndiye mwanzilishi wa DÉFI hii: huwezi kuwapigia kura washiriki.'},
