  // ── Administration : retraits (validation à deux, signaux de risque) ──
  'Tu ne peux pas traiter ta propre demande de retrait.': {'en': 'You cannot process your own withdrawal request.', 'es': 'No puedes tramitar tu propia solicitud de retiro.', 'de': 'Du kannst deine eigene Auszahlungsanfrage nicht bearbeiten.', 'ar': 'لا يمكنك معالجة طلب السحب الخاص بك.', 'pt': 'Você não pode processar seu próprio pedido de saque.', 'zh': '你不能处理自己的提现申请。', 'sw': 'Huwezi kushughulikia ombi lako mwenyewe la uondoaji.'},
  'Ce retrait doit d’abord être validé par une personne de l’équipe, puis payé par une autre.': {'en': 'This withdrawal must first be validated by one team member, then paid by another.', 'es': 'Este retiro debe ser validado primero por un miembro del equipo y pagado después por otro.', 'de': 'Diese Auszahlung muss zuerst von einer Person im Team bestätigt und dann von einer anderen bezahlt werden.', 'ar': 'يجب أن يوافق على هذا السحب أولًا أحد أعضاء الفريق، ثم يدفعه عضو آخر.', 'pt': 'Este saque deve ser validado primeiro por um membro da equipe e pago depois por outro.', 'zh': '此笔提现须先由一名团队成员审核，再由另一名成员付款。', 'sw': 'Uondoaji huu lazima uidhinishwe kwanza na mwanatimu mmoja, kisha ulipwe na mwingine.'},
  'Cette demande a déjà été traitée.': {'en': 'This request has already been processed.', 'es': 'Esta solicitud ya fue tramitada.', 'de': 'Diese Anfrage wurde bereits bearbeitet.', 'ar': 'تمت معالجة هذا الطلب بالفعل.', 'pt': 'Este pedido já foi processado.', 'zh': '此申请已处理。', 'sw': 'Ombi hili tayari limeshughulikiwa.'},
  'Compte de moins de 30 jours': {'en': 'Account less than 30 days old', 'es': 'Cuenta con menos de 30 días', 'de': 'Konto jünger als 30 Tage', 'ar': 'حساب عمره أقل من 30 يومًا', 'pt': 'Conta com menos de 30 dias', 'zh': '账号注册不满 30 天', 'sw': 'Akaunti ya chini ya siku 30'},
  'Gains convertis ou encaissés dans les dernières 24 h': {'en': 'Earnings converted or cashed in during the last 24 h', 'es': 'Ganancias convertidas o cobradas en las últimas 24 h', 'de': 'In den letzten 24 Std. umgewandelte oder eingelöste Einnahmen', 'ar': 'أرباح تم تحويلها أو تحصيلها خلال آخر 24 ساعة', 'pt': 'Ganhos convertidos ou resgatados nas últimas 24 h', 'zh': '最近 24 小时内兑换或提取过收益', 'sw': 'Mapato yaliyobadilishwa au kuchukuliwa katika saa 24 zilizopita'},
  'Gros montant : deux personnes de l’équipe doivent approuver': {'en': 'Large amount: two team members must approve', 'es': 'Importe elevado: dos miembros del equipo deben aprobar', 'de': 'Hoher Betrag: Zwei Teammitglieder müssen zustimmen', 'ar': 'مبلغ كبير: يجب أن يوافق عضوان من الفريق', 'pt': 'Valor alto: dois membros da equipe devem aprovar', 'zh': '大额：需两名团队成员批准', 'sw': 'Kiasi kikubwa: wanatimu wawili lazima waidhinishe'},
  'Validé en premier par': {'en': 'First validated by', 'es': 'Validado primero por', 'de': 'Zuerst bestätigt von', 'ar': 'تمت الموافقة أولًا من', 'pt': 'Validado primeiro por', 'zh': '首先审核人', 'sw': 'Aliyeidhinisha kwanza'},
  'personne pour le moment': {'en': 'nobody yet', 'es': 'nadie por ahora', 'de': 'noch niemand', 'ar': 'لا أحد حتى الآن', 'pt': 'ninguém por enquanto', 'zh': '暂无', 'sw': 'hakuna bado'},
  'Signaux de risque': {'en': 'Risk signals', 'es': 'Señales de riesgo', 'de': 'Risikosignale', 'ar': 'مؤشرات الخطر', 'pt': 'Sinais de risco', 'zh': '风险信号', 'sw': 'Ishara za hatari'},
  'Gros montant : une première personne valide, une autre personne de l’équipe paie.': {'en': 'Large amount: one person validates, another team member pays.', 'es': 'Importe elevado: una persona valida y otra persona del equipo paga.', 'de': 'Hoher Betrag: Eine Person bestätigt, eine andere Person im Team zahlt.', 'ar': 'مبلغ كبير: يوافق شخص أولًا، ثم يدفع شخص آخر من الفريق.', 'pt': 'Valor alto: uma pessoa valida e outra pessoa da equipe paga.', 'zh': '大额：由一人审核，另一名团队成员付款。', 'sw': 'Kiasi kikubwa: mtu mmoja anaidhinisha, mwanatimu mwingine analipa.'},
  'VALIDER (1re approbation)': {'en': 'VALIDATE (1st approval)', 'es': 'VALIDAR (1.ª aprobación)', 'de': 'BESTÄTIGEN (1. Freigabe)', 'ar': 'موافقة (الأولى)', 'pt': 'VALIDAR (1.ª aprovação)', 'zh': '审核（第一次批准）', 'sw': 'IDHINISHA (idhini ya 1)'},
  'En attente d’un second approbateur : tu as validé ce retrait, une autre personne de l’équipe doit le payer.': {'en': 'Waiting for a second approver: you validated this withdrawal, another team member must pay it.', 'es': 'A la espera de un segundo aprobador: validaste este retiro, otra persona del equipo debe pagarlo.', 'de': 'Warten auf einen zweiten Freigeber: Du hast diese Auszahlung bestätigt, eine andere Person im Team muss sie bezahlen.', 'ar': 'في انتظار موافق ثانٍ: لقد وافقت على هذا السحب، ويجب أن يدفعه شخص آخر من الفريق.', 'pt': 'Aguardando um segundo aprovador: você validou este saque, outra pessoa da equipe deve pagá-lo.', 'zh': '等待第二位批准人：你已审核此笔提现，须由另一名团队成员付款。', 'sw': 'Inasubiri mwidhinishaji wa pili: umeidhinisha uondoaji huu, mwanatimu mwingine lazima aulipe.'},
  'CONFIRMER LE PAIEMENT': {'en': 'CONFIRM PAYMENT', 'es': 'CONFIRMAR EL PAGO', 'de': 'ZAHLUNG BESTÄTIGEN', 'ar': 'تأكيد الدفع', 'pt': 'CONFIRMAR O PAGAMENTO', 'zh': '确认付款', 'sw': 'THIBITISHA MALIPO'},
  'Retrait validé. Une autre personne de l’équipe doit maintenant le payer.': {'en': 'Withdrawal validated. Another team member must now pay it.', 'es': 'Retiro validado. Ahora otra persona del equipo debe pagarlo.', 'de': 'Auszahlung bestätigt. Jetzt muss eine andere Person im Team sie bezahlen.', 'ar': 'تمت الموافقة على السحب. يجب الآن أن يدفعه شخص آخر من الفريق.', 'pt': 'Saque validado. Agora outra pessoa da equipe deve pagá-lo.', 'zh': '提现已审核。现在须由另一名团队成员付款。', 'sw': 'Uondoaji umeidhinishwa. Sasa mwanatimu mwingine lazima aulipe.'},
  'Opération impossible': {'en': 'Operation not possible', 'es': 'Operación imposible', 'de': 'Vorgang nicht möglich', 'ar': 'العملية غير ممكنة', 'pt': 'Operação impossível', 'zh': '无法执行此操作', 'sw': 'Shughuli haiwezekani'},

